def copy_customer(apps, schema_editor):
    Artwork = apps.get_model("masters", "Artwork")
    for art in Artwork.objects.exclude(customer=None):
        art.customers.add(art.customer_id)


def map_supplier_categories(apps, schema_editor):
    """Free-text categories -> the fixed list (unrecognised ones become Other)."""
    Supplier = apps.get_model("masters", "Supplier")
    words = [("label", "labels"), ("sticker", "labels"), ("masterbatch", "masterbatch"), ("polymer", "polymer"),
             ("pack", "packing"), ("box", "packing"), ("carton", "packing"), ("spare", "spares"), ("maint", "spares"), ("service", "services")]
    for sup in Supplier.objects.exclude(category=""):
        text = sup.category.lower()
        sup.category = next((code for word, code in words if word in text), "other")
        sup.save(update_fields=["category"])


